<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Falling Sand Sandbox</title>
<style>
  :root {
    color-scheme: dark;
    --panel: #171b23;
    --border: #303847;
    --text: #e8edf6;
    --muted: #929cad;
  }

  * { box-sizing: border-box; }

  body {
    min-height: 100vh;
    margin: 0;
    display: grid;
    place-items: center;
    overflow-x: hidden;
    background:
      radial-gradient(circle at 50% 20%, #202838 0, #10141c 48%, #090b10 100%);
    color: var(--text);
    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  }

  main {
    width: min(94vw, 720px);
    padding: 24px;
    text-align: center;
  }

  h1 {
    margin: 0 0 5px;
    font-size: clamp(1.35rem, 4vw, 2rem);
    letter-spacing: .04em;
  }

  .subtitle {
    margin: 0 0 17px;
    color: var(--muted);
    font-size: .9rem;
  }

  .controls {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 8px;
    margin-bottom: 14px;
  }

  button {
    min-width: 76px;
    padding: 9px 13px;
    border: 1px solid var(--border);
    border-radius: 9px;
    background: var(--panel);
    color: var(--text);
    font: inherit;
    font-size: .86rem;
    font-weight: 700;
    cursor: pointer;
    transition: transform .1s, border-color .1s, background .1s, box-shadow .1s;
  }

  button:hover {
    transform: translateY(-1px);
    border-color: #697488;
  }

  button:active { transform: translateY(1px); }

  button.active {
    border-color: var(--accent, #fff);
    background: color-mix(in srgb, var(--accent, #fff) 18%, var(--panel));
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent, #fff) 22%, transparent);
  }

  #mat-sand { --accent: #e4b95d; }
  #mat-water { --accent: #388ee8; }
  #mat-wall { --accent: #8f99a8; }
  #mat-acid { --accent: #80e34f; }
  #mat-empty { --accent: #e07070; }
  #clear { margin-left: 8px; }

  .canvas-shell {
    width: min(88vw, 560px);
    height: min(88vw, 560px);
    min-width: 400px;
    min-height: 400px;
    margin: auto;
    padding: 5px;
    border: 1px solid #354052;
    border-radius: 12px;
    background: #121721;
    box-shadow: 0 18px 55px #0009, inset 0 0 16px #fff06;
  }

  #sand {
    display: block;
    width: 100%;
    height: 100%;
    min-width: 390px;
    min-height: 390px;
    border-radius: 7px;
    background: #080b10;
    image-rendering: pixelated;
    cursor: crosshair;
    touch-action: none;
  }

  .hint {
    margin: 12px 0 0;
    color: var(--muted);
    font-size: .78rem;
  }

  @media (max-width: 455px) {
    main { width: 100%; padding: 12px 4px; }
    .canvas-shell {
      width: 400px;
      height: 400px;
    }
    button { min-width: 68px; padding: 8px 9px; }
  }
</style>
</head>
<body>
<main>
  <h1>Elemental Sandbox</h1>
  <p class="subtitle">Paint matter and watch it settle.</p>

  <div class="controls" aria-label="Materials">
    <button id="mat-sand" class="active" type="button">Sand</button>
    <button id="mat-water" type="button">Water</button>
    <button id="mat-wall" type="button">Wall</button>
    <button id="mat-acid" type="button">Acid</button>
    <button id="mat-empty" type="button">Eraser</button>
    <button id="clear" type="button">Clear</button>
  </div>

  <div class="canvas-shell">
    <canvas id="sand" width="100" height="100" aria-label="Falling sand simulation"></canvas>
  </div>

  <p class="hint">Drag to paint · larger brush for flowing materials</p>
</main>

<script>
(() => {
  "use strict";

  const W = 100;
  const H = 100;
  const EMPTY = 0;
  const SAND = 1;
  const WATER = 2;
  const WALL = 3;
  const ACID = 4;

  const names = ["empty", "sand", "water", "wall", "acid"];
  const codes = Object.freeze({
    empty: EMPTY,
    sand: SAND,
    water: WATER,
    wall: WALL,
    acid: ACID
  });

  const canvas = document.getElementById("sand");
  const ctx = canvas.getContext("2d", { alpha: false });
  const grid = new Uint8Array(W * H);
  const moved = new Uint8Array(W * H);
  const pixels = ctx.createImageData(W, H);
  let selected = SAND;
  let painting = false;
  let lastCell = null;
  let seed = 0x71c3a529;

  function index(x, y) {
    return y * W + x;
  }

  function valid(x, y) {
    return x >= 0 && x < W && y >= 0 && y < H;
  }

  function random() {
    seed ^= seed << 13;
    seed ^= seed >>> 17;
    seed ^= seed << 5;
    return (seed >>> 0) / 4294967296;
  }

  function shuffledDirections() {
    return random() < 0.5 ? [-1, 1] : [1, -1];
  }

  function move(x1, y1, x2, y2) {
    const from = index(x1, y1);
    const to = index(x2, y2);
    grid[to] = grid[from];
    grid[from] = EMPTY;
    moved[to] = 1;
  }

  /*
    Sink sand without carrying liquid vertically up a falling column.
    Displaced liquid escapes beside the destination whenever local room exists.
    If completely enclosed, the sand and liquid remain where they are until
    sideways room opens.
  */
  function sinkIntoLiquid(x, y, nx, ny) {
    const destination = index(nx, ny);
    const liquid = grid[destination];
    const dirs = shuffledDirections();
    const escapeSites = [
      [nx + dirs[0], ny],
      [nx + dirs[1], ny],
      [nx + dirs[0], ny - 1],
      [nx + dirs[1], ny - 1]
    ];

    for (const [ex, ey] of escapeSites) {
      if (
        ex > 0 && ex < W - 1 &&
        ey >= 0 && ey < H &&
        grid[index(ex, ey)] === EMPTY
      ) {
        grid[index(x, y)] = EMPTY;
        grid[destination] = SAND;
        grid[index(ex, ey)] = liquid;
        moved[destination] = 1;
        moved[index(ex, ey)] = 1;
        return true;
      }
    }
    return false;
  }

  function updateSand(x, y) {
    if (y >= H - 1) return;
    const below = grid[index(x, y + 1)];

    if (below === EMPTY) {
      move(x, y, x, y + 1);
      return;
    }

    if (below === WATER || below === ACID) {
      if (sinkIntoLiquid(x, y, x, y + 1)) return;
    }

    const dirs = shuffledDirections();
    for (const dx of dirs) {
      const nx = x + dx;
      const ny = y + 1;
      if (nx < 0 || nx >= W) continue;
      const target = grid[index(nx, ny)];

      if (target === EMPTY) {
        move(x, y, nx, ny);
        return;
      }

      if ((target === WATER || target === ACID) &&
          sinkIntoLiquid(x, y, nx, ny)) {
        return;
      }
    }
  }

  function updateWaterLike(x, y, material) {
    if (y < H - 1 && grid[index(x, y + 1)] === EMPTY) {
      move(x, y, x, y + 1);
      return;
    }

    if (y < H - 1) {
      const diagonals = shuffledDirections();
      for (const dx of diagonals) {
        const nx = x + dx;
        if (nx >= 0 && nx < W &&
            grid[index(nx, y + 1)] === EMPTY) {
          move(x, y, nx, y + 1);
          return;
        }
      }
    }

    const horizontal = shuffledDirections();
    for (const dx of horizontal) {
      const nx = x + dx;
      if (nx >= 0 && nx < W &&
          grid[index(nx, y)] === EMPTY) {
        move(x, y, nx, y);
        return;
      }
    }
  }

  function updateAcid(x, y) {
    const targets = [];
    if (y < H - 1) targets.push([x, y + 1]);
    if (x > 0) targets.push([x - 1, y]);
    if (x < W - 1) targets.push([x + 1, y]);

    for (let i = targets.length - 1; i > 0; i--) {
      const j = Math.floor(random() * (i + 1));
      [targets[i], targets[j]] = [targets[j], targets[i]];
    }

    for (const [tx, ty] of targets) {
      const ti = index(tx, ty);
      if (grid[ti] === SAND || grid[ti] === WALL) {
        grid[ti] = EMPTY;
        moved[index(x, y)] = 1;
        return;
      }
    }

    updateWaterLike(x, y, ACID);
  }

  function step() {
    moved.fill(0);

    for (let y = H - 1; y >= 0; y--) {
      const leftToRight = random() < 0.5;

      for (let n = 0; n < W; n++) {
        const x = leftToRight ? n : W - 1 - n;
        const i = index(x, y);
        if (moved[i]) continue;

        const material = grid[i];
        if (material === SAND) updateSand(x, y);
        else if (material === WATER) updateWaterLike(x, y, WATER);
        else if (material === ACID) updateAcid(x, y);
      }
    }
  }

  function render() {
    const data = pixels.data;

    for (let i = 0; i < grid.length; i++) {
      const p = i * 4;
      const x = i % W;
      const y = (i / W) | 0;
      let r, g, b;

      switch (grid[i]) {
        case SAND: {
          const variation = ((x * 13 + y * 7) % 19) - 9;
          r = 225 + variation;
          g = 180 + variation;
          b = 82 + (variation >> 1);
          break;
        }
        case WATER:
          r = 34;
          g = 112 + ((x + y) % 12);
          b = 208 + ((x * 3 + y) % 18);
          break;
        case WALL: {
          const shade = 110 + ((x * 5 + y * 3) % 25);
          r = shade;
          g = shade + 7;
          b = shade + 17;
          break;
        }
        case ACID:
          r = 91 + ((x + y) % 20);
          g = 218 + ((x * 2 + y) % 28);
          b = 53;
          break;
        default:
          r = 7;
          g = 10;
          b = 15;
      }

      data[p] = r;
      data[p + 1] = g;
      data[p + 2] = b;
      data[p + 3] = 255;
    }

    ctx.putImageData(pixels, 0, 0);
  }

  function clearGrid() {
    grid.fill(EMPTY);
    moved.fill(0);
    seed = 0x71c3a529;
    render();
  }

  function cellFromEvent(event) {
    const rect = canvas.getBoundingClientRect();
    return {
      x: Math.max(0, Math.min(W - 1,
        Math.floor((event.clientX - rect.left) * W / rect.width))),
      y: Math.max(0, Math.min(H - 1,
        Math.floor((event.clientY - rect.top) * H / rect.height)))
    };
  }

  function dab(cx, cy) {
    const radius = selected === WALL ? 1 : selected === EMPTY ? 3 : 2;

    for (let dy = -radius; dy <= radius; dy++) {
      for (let dx = -radius; dx <= radius; dx++) {
        if (dx * dx + dy * dy > radius * radius + 1) continue;
        const x = cx + dx;
        const y = cy + dy;
        if (valid(x, y)) grid[index(x, y)] = selected;
      }
    }
  }

  function paintLine(from, to) {
    let x0 = from.x;
    let y0 = from.y;
    const x1 = to.x;
    const y1 = to.y;
    const dx = Math.abs(x1 - x0);
    const sx = x0 < x1 ? 1 : -1;
    const dy = -Math.abs(y1 - y0);
    const sy = y0 < y1 ? 1 : -1;
    let error = dx + dy;

    while (true) {
      dab(x0, y0);
      if (x0 === x1 && y0 === y1) break;
      const twice = 2 * error;
      if (twice >= dy) {
        error += dy;
        x0 += sx;
      }
      if (twice <= dx) {
        error += dx;
        y0 += sy;
      }
    }
    render();
  }

  canvas.addEventListener("pointerdown", event => {
    painting = true;
    canvas.setPointerCapture(event.pointerId);
    lastCell = cellFromEvent(event);
    dab(lastCell.x, lastCell.y);
    render();
  });

  canvas.addEventListener("pointermove", event => {
    if (!painting) return;
    const cell = cellFromEvent(event);
    paintLine(lastCell, cell);
    lastCell = cell;
  });

  function stopPainting() {
    painting = false;
    lastCell = null;
  }

  canvas.addEventListener("pointerup", stopPainting);
  canvas.addEventListener("pointercancel", stopPainting);

  const materialButtons = {
    "mat-sand": SAND,
    "mat-water": WATER,
    "mat-wall": WALL,
    "mat-acid": ACID,
    "mat-empty": EMPTY
  };

  for (const [id, material] of Object.entries(materialButtons)) {
    document.getElementById(id).addEventListener("click", () => {
      selected = material;
      for (const buttonId of Object.keys(materialButtons)) {
        document.getElementById(buttonId)
          .classList.toggle("active", buttonId === id);
      }
    });
  }

  document.getElementById("clear").addEventListener("click", clearGrid);

  window.sim = Object.freeze({
    w: W,
    h: H,

    tick(n = 1) {
      n = Math.max(0, Math.floor(Number(n) || 0));
      for (let i = 0; i < n; i++) step();
      render();
    },

    get(x, y) {
      x = Math.trunc(x);
      y = Math.trunc(y);
      if (!valid(x, y)) return undefined;
      return names[grid[index(x, y)]];
    },

    set(x, y, material) {
      x = Math.trunc(x);
      y = Math.trunc(y);
      if (!valid(x, y)) return false;
      if (!Object.prototype.hasOwnProperty.call(codes, material)) {
        throw new TypeError("Unknown material: " + material);
      }
      grid[index(x, y)] = codes[material];
      render();
      return true;
    },

    clear: clearGrid
  });

  let previousTime = performance.now();
  let accumulator = 0;
  const stepDuration = 1000 / 60;

  function animate(time) {
    accumulator += Math.min(100, time - previousTime);
    previousTime = time;

    while (accumulator >= stepDuration) {
      step();
      accumulator -= stepDuration;
    }

    render();
    requestAnimationFrame(animate);
  }

  render();
  requestAnimationFrame(animate);
})();
</script>
</body>
</html>
